<?php require_once 'config/database.php';require_once 'includes/functions.php';require_login();$rows=$conn->query('SELECT s.id,s.total,s.sold_at,u.name user_name,COUNT(si.id) line_count FROM sales s LEFT JOIN users u ON u.id=s.user_id LEFT JOIN sale_items si ON si.sale_id=s.id GROUP BY s.id ORDER BY s.id DESC');$pageTitle='Sales History';$active='history';require 'includes/header.php';?><div class="card"><div class="card-header"><h3 class="card-title">Recorded Sales</h3><a class="btn btn-success btn-sm float-right" href="sales.php"><i class="fas fa-plus"></i> New Sale</a></div><div class="card-body table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Sale #</th><th>Date & Time</th><th>Recorded By</th><th>Items</th><th>Total</th><th>Details</th></tr></thead><tbody><?php if(!$rows->num_rows):?><tr><td colspan="6">No sales recorded yet.</td></tr><?php else:while($r=$rows->fetch_assoc()):?><tr><td>#<?=$r['id']?></td><td><?=e($r['sold_at'])?></td><td><?=e($r['user_name']??'Deleted user')?></td><td><?=$r['line_count']?></td><td><?=money($r['total'])?></td><td><button class="btn btn-info btn-sm" data-toggle="modal" data-target="#sale<?=$r['id']?>">View</button></td></tr><?php endwhile;endif;?></tbody></table></div></div>
<?php $rows->data_seek(0);while($r=$rows->fetch_assoc()):$sid=(int)$r['id'];$st=$conn->prepare('SELECT product_name,quantity,unit_price,subtotal FROM sale_items WHERE sale_id=?');$st->bind_param('i',$sid);$st->execute();$items=$st->get_result();?><div class="modal fade" id="sale<?=$sid?>"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h4 class="modal-title">Sale #<?=$sid?> details</h4><button type="button" class="close" data-dismiss="modal">&times;</button></div><div class="modal-body"><table class="table"><thead><tr><th>Product</th><th>Qty</th><th>Price</th><th>Subtotal</th></tr></thead><tbody><?php while($i=$items->fetch_assoc()):?><tr><td><?=e($i['product_name'])?></td><td><?=$i['quantity']?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['subtotal'])?></td></tr><?php endwhile;?></tbody></table><h5 class="text-right">Total: <?=money($r['total'])?></h5></div></div></div></div><?php endwhile;require 'includes/footer.php';?>
